    Differential Revision: https://phabricator.services.mozilla.com/D250038

diff --git a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
index ff0c5017d1e..ec245956a65 100644
--- a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
+++ b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
@@ -81,7 +81,8 @@ export const InAppNotifications = {
         lazy.NotificationUpdater.readyToUpdate
       ) {
         await this.updateNotifications(
-          await lazy.OfflineNotifications.getDefaultNotifications()
+          await lazy.OfflineNotifications.getDefaultNotifications(),
+          true
         );
         return;
       }
@@ -93,29 +94,32 @@ export const InAppNotifications = {
    * Update the notifications cache.
    *
    * @param {object[]} notifications
+   * @param {boolean} [skipCleanup=false] - Skip cleanup operations on state fields.
    */
-  async updateNotifications(notifications) {
+  async updateNotifications(notifications, skipCleanup = false) {
     this._jsonFile.data.notifications = notifications;

-    const notificationIds = new Set(
-      notifications.map(notification => notification.id)
-    );
-    const defaultNotificationIds =
-      await lazy.OfflineNotifications.getDefaultNotificationIds();
-    const allNotificationIds = notificationIds.union(defaultNotificationIds);
-    const interactedWithSet = new Set(this._jsonFile.data.interactedWith);
-    const stillExistingInteractedWith =
-      interactedWithSet.intersection(allNotificationIds);
-    if (stillExistingInteractedWith.size < interactedWithSet.size) {
-      this._jsonFile.data.interactedWith = Array.from(
-        stillExistingInteractedWith
+    if (!skipCleanup) {
+      const notificationIds = new Set(
+        notifications.map(notification => notification.id)
+      );
+      const defaultNotificationIds =
+        await lazy.OfflineNotifications.getDefaultNotificationIds();
+      const allNotificationIds = notificationIds.union(defaultNotificationIds);
+      const interactedWithSet = new Set(this._jsonFile.data.interactedWith);
+      const stillExistingInteractedWith =
+        interactedWithSet.intersection(allNotificationIds);
+      if (stillExistingInteractedWith.size < interactedWithSet.size) {
+        this._jsonFile.data.interactedWith = Array.from(
+          stillExistingInteractedWith
+        );
+      }
+      this._jsonFile.data.seeds = Object.fromEntries(
+        Object.entries(this._jsonFile.data.seeds).filter(([notificationId]) =>
+          allNotificationIds.has(notificationId)
+        )
       );
     }
-    this._jsonFile.data.seeds = Object.fromEntries(
-      Object.entries(this._jsonFile.data.seeds).filter(([notificationId]) =>
-        allNotificationIds.has(notificationId)
-      )
-    );
     this._updateNotificationManager();

     this._jsonFile.saveSoon();
diff --git a/mail/components/inappnotifications/test/unit/test_in_app_notifications.js b/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
index e866f2193c1..bfd2960e695 100644
--- a/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
+++ b/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
@@ -546,3 +546,25 @@ add_task(async function test_scheduledNotification() {

   await InAppNotifications.updateNotifications([]);
 });
+
+add_task(async function test_updateNotifications_noCleanup() {
+  const mockData = getMockNotifications();
+  await InAppNotifications.updateNotifications(mockData);
+  const notificationId = mockData[0].id;
+  InAppNotifications.markAsInteractedWith(notificationId);
+  const seed = InAppNotifications._getSeed(notificationId);
+
+  await InAppNotifications.updateNotifications([], true);
+
+  Assert.ok(
+    InAppNotifications._jsonFile.data.interactedWith.includes(notificationId),
+    `Should preserve interacted with ${notificationId}`
+  );
+  Assert.equal(
+    InAppNotifications._getSeed(notificationId),
+    seed,
+    `Seed for ${notificationId} should stay the same`
+  );
+
+  await InAppNotifications.updateNotifications([]);
+});
